const icons={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2Zm6-2v16m6-14v16',flask:'M9 3h6m-5 0v7L4 20q-1 1 1 1h14q2 0 1-1l-6-10V3M7 15h10',layers:'m12 3 10 6-10 6L2 9Zm-9 11 9 5 9-5M3 18l9 5 9-5',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.9M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8m8 0a4 4 0 0 1 0 8',book:'M4 3h14a2 2 0 0 1 2 2v16H6a3 3 0 0 1-3-3V5a2 2 0 0 1 1-2Zm0 14h16M7 7h9m-9 4h6',arrow:'M4 12h15m-6-6 6 6-6 6',spark:'m12 3 2.8 6.2L21 12l-6.2 2.8L12 21l-2.8-6.2L3 12l6.2-2.8Z',brain:'M12 4v16m0-14C8 0 3 4 5 8c-5 2-3 7 0 7-1 5 5 7 7 3m0-12c4-6 9-2 7 2 5 2 3 7 0 7 1 5-5 7-7 3M5 8l3 1m11-1-3 1M5 15l3-2m11 2-3-2',terminal:'m5 7 5 5-5 5m8 0h6M3 3h18v18H3Z',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm10-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6',loop:'M20 7A9 9 0 0 0 5 5L2 8m0-5v5h5m-3 9a9 9 0 0 0 15 2l3-3m0 5v-5h-5',shield:'m12 2 9 4v7c-1 5-5 8-9 9-4-1-8-4-9-9V6Zm-4 10 3 3 5-6',memory:'M5 5h14v14H5Zm4 4h6v6H9Zm0-7v3m6-3v3M9 19v3m6-3v3M2 9h3m-3 6h3m14-6h3m-3 6h3',check:'m5 12 4 4L19 6',code:'m8 5-6 7 6 7m8-14 6 7-6 7m-3-16-2 18',sprout:'M12 21v-9m0 4C4 16 2 11 3 6c6-1 10 3 9 10Zm0-4c0-7 4-10 9-9 1 5-3 9-9 9',menu:'M3 6h18M3 12h18M3 18h18',link:'m10 13 4-4m-6 7-1 1a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0m2 0 1-1a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',flag:'M5 22V3m0 1c5-4 9 4 14 0v11c-5 4-9-4-14 0'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true" viewBox="0 0 24 24"><path d="${icons[name]||icons.spark}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
import {lessons,agents,socialMappings} from './content.js';
let state={completed:[],answers:{},notes:{},last:1,capstone:false};
try{const saved=JSON.parse(localStorage.getItem('agent-lab-v1'));if(saved&&typeof saved==='object'){state={...state,...saved,completed:Array.isArray(saved.completed)?saved.completed.filter(n=>Number.isInteger(n)&&n>=1&&n<=8):[],answers:saved.answers&&typeof saved.answers==='object'?saved.answers:{},notes:saved.notes&&typeof saved.notes==='object'?saved.notes:{}};}}catch{}
state.completed=[...new Set(state.completed)];
state.last=Number.isInteger(state.last)&&state.last>=1&&state.last<=8?state.last:1;
state.capstone=state.capstone===true;
state.notes=Object.fromEntries(Object.entries(state.notes).filter(([k,v])=>/^[1-8]$/.test(k)&&typeof v==='string').map(([k,v])=>[k,v.slice(0,5000)]));
state.answers=Object.fromEntries(Object.entries(state.answers).filter(([k,v])=>/^[1-8]$/.test(k)&&Number.isInteger(v)&&v>=0&&v<=2));
const save=()=>{try{localStorage.setItem('agent-lab-v1',JSON.stringify(state));}catch{toast('浏览器未允许保存，当前学习仍可继续。');}};
let toastTimer;function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3200);}
let introAnswer=null;
const navItems=[['/','home','探索首页',''],['/course/1','map','学习路线','08'],['/lab','flask','交互实验室','03'],['/atlas','layers','Agent 图鉴','07'],['/society','people','社会的镜像',''],['/notebook','book','我的学习档案','']];
function shell(body,section='/',label='探索首页'){
 const nav=navItems.map(([url,i,t,n])=>`<a class="nav-item ${section===url||section.startsWith(url.split('/').slice(0,2).join('/'))&&url!=='/'?'active':section==='/'&&url==='/'?'active':''}" href="#${url}" ${section===url?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${n?`<span class="count">${n}</span>`:''}</a>`).join('');
 document.getElementById('app').innerHTML=`<button class="mobile-scrim" aria-label="关闭导航"></button><aside class="sidebar" aria-label="主导航"><a class="brand" href="#/"><span class="brandmark">A</span><span><strong>Agent 实验局</strong><small>THE AGENT LAB</small></span></a><div class="nav-label">从语言，到行动</div><nav>${nav}</nav><div class="sidebar-note">${icon('sprout','sprout')}<strong>理解，比追赶更有力量。</strong><p>产品会迭代。掌握底层原理，<br>你就拥有一张不会过期的地图。</p></div><div class="sidebar-bottom"><span class="avatar">你</span><span>独立探索者</span><span style="margin-left:auto">Lv.${1+Math.floor(state.completed.length/2)}</span></div></aside><div class="workspace"><header class="topbar"><button class="mobile-toggle" aria-label="打开导航" aria-expanded="false">${icon('menu')}</button><div class="breadcrumb"><span class="desktop-crumb">实验局</span><span class="desktop-crumb">/</span><b>${label}</b></div><div class="top-status"><span class="xp">${icon('spark')}<span id="xp-count">${state.completed.length*100+(state.capstone?200:0)}</span> XP</span><span class="top-rule"></span><span class="local-label">进度保存在这台设备</span><span class="avatar">你</span></div></header><main id="main" class="main" tabindex="-1">${body}<footer class="footer"><span>Agent 实验局 · 让每一次「原来如此」都有迹可循</span><span>自主探索 · 本地记录 · 资料核对于 2026.09.12</span></footer></main></div>`;
 document.querySelector('.mobile-toggle').onclick=()=>{document.querySelector('.sidebar').classList.add('open');document.querySelector('.mobile-scrim').classList.add('visible');document.querySelector('.mobile-toggle').setAttribute('aria-expanded','true');};
 document.querySelector('.mobile-scrim').onclick=()=>{document.querySelector('.sidebar').classList.remove('open');document.querySelector('.mobile-scrim').classList.remove('visible');document.querySelector('.mobile-toggle').setAttribute('aria-expanded','false');};
 document.title=`${label} · Agent 实验局`;
}
function diagram(){return `<div class="diagram-area"><div class="diagram-label">THE SMALLEST AGENT LOOP</div><div class="diagram"><svg class="diagram-path" viewBox="0 0 420 220" preserveAspectRatio="none" aria-hidden="true"><path d="M115 42H310V180H115V42"/><circle class="flow-dot" r="4" cx="218" cy="42"/></svg><div class="d-node model"><span class="node-icon">${icon('brain')}</span><span><strong>语言模型</strong><small>决定下一步 · MODEL</small></span></div><div class="d-node"><span class="node-icon">${icon('terminal')}</span><span><strong>工具执行</strong><small>改变外部世界 · ACT</small></span></div><div class="d-node"><span class="node-icon">${icon('loop')}</span><span><strong>循环调度</strong><small>带着结果再来 · LOOP</small></span></div><div class="d-node"><span class="node-icon">${icon('eye')}</span><span><strong>观察结果</strong><small>知道发生了什么 · OBSERVE</small></span></div></div><div class="diagram-footer"><span>模型提出行动，程序执行，再把结果交回。</span></div></div>`;}
function home(){shell(`<div class="welcome"><div><h1>${state.completed.length?'欢迎回来，探索者。':'你好，未来的 Agent 创造者。'}</h1><p>不用先读完一本书。动手试一下，理解就会开始。</p></div><span class="date-stamp">${icon('sprout')}你的第一天，也是一个好起点</span></div><section class="hero"><div class="hero-copy"><div class="eyebrow">从 0 出发 · 以理解为终点</div><h1>别只和 AI 聊天。<br>教它<em>把事情做成。</em></h1><p>拆开那个看似神奇的黑盒。用 8 个关卡、3 个实验，亲手走过从语言到行动的那一步。</p><div class="hero-actions"><a class="btn primary" href="#/course/${state.last||1}">${state.completed.length?'继续我的探索':'开启第一关'} ${icon('arrow')}</a><a class="text-link" href="#/lab">先去实验室玩玩 ${icon('arrow')}</a></div></div>${diagram()}</section><div class="section-head"><div><h2>${icon('spark')}先来一个 30 秒思想实验</h2></div><span class="tag">零基础可玩</span></div><div class="two-col"><section class="card challenge"><div class="card-kicker">EXPERIMENT 00 / 会说 ≠ 会做</div><h3>「请帮我打开房间里的灯。」</h3><p>模型回复「灯已经打开了」，但它没有连接任何设备。此时，灯会亮吗？</p><div class="challenge-options"><button class="choice" data-intro="0"><span class="choice-letter">A</span>会，它说已经完成了</button><button class="choice" data-intro="1"><span class="choice-letter">B</span>不会，语言还没有变成行动</button></div><div id="intro-feedback" aria-live="polite"></div></section><aside class="card quote-card"><div class="quote-mark">“</div><blockquote>如果语言模型是一个聪明的实习生，<br>谁给它工位、工具和办事流程？</blockquote><p>这就是 Harness 的工作。你将在第 5 关拆开它。</p><a href="#/course/5" class="text-link" style="margin-top:13px">从「实习生」看懂 Agent ${icon('arrow')}</a></aside></div><div class="section-head"><div><h2>你的探索路线</h2><p>先理解，再实验，最后用自己的话讲出来。</p></div><span class="text-link">${state.completed.length} / 8 已掌握</span></div><div id="home-courses" class="course-grid"></div><div class="section-head"><div><h2>同一个原理，七种生长方式</h2><p>不做排名。看清每个 Agent 选择了什么，又放弃了什么。</p></div><a class="text-link" href="#/atlas">打开图鉴 ${icon('arrow')}</a></div><div class="brand-strip">${['Codex','Claude Code','OpenClaw','Hermes','OpenCode','Pi','DeepSeek Harness'].map((n,i)=>`<a class="brand-chip" href="#/atlas/${['codex','claude','openclaw','hermes','opencode','pi','deepseek'][i]}"><span class="brand-symbol">${['⌘','✳','↗','H','&gt;_','π','D'][i]}</span>${n}</a>`).join('')}</div>`);
 document.querySelectorAll('[data-intro]').forEach(b=>b.onclick=()=>{introAnswer=Number(b.dataset.intro);renderIntro();});renderIntro();
 if(typeof courseCards==='function')document.getElementById('home-courses').innerHTML=courseCards();
}
function renderIntro(){if(introAnswer===null)return;document.getElementById('intro-feedback').innerHTML=`<div class="feedback ${introAnswer===0?'error':''}">${introAnswer===1?'没错！':'试着区分「说了什么」和「发生了什么」。'}模型的输出只是一段信息。要开灯，还需要工具接口、实际执行，以及设备状态的回传。<a href="#/course/1" class="source-link">把这个发现带进第一关 →</a></div>`;document.querySelectorAll('[data-intro]').forEach(b=>{b.classList.toggle('correct',Number(b.dataset.intro)===1);b.classList.toggle('wrong',Number(b.dataset.intro)===0&&introAnswer===0);});}
function courseCards(){return lessons.map(l=>`<a href="#/course/${l.id}" class="course-card"><div class="course-card-top"><span class="course-num">${String(l.id).padStart(2,'0')}</span><span class="course-icon">${icon(state.completed.includes(l.id)?'check':l.icon)}</span></div><h3>${l.title}</h3><p>${l.subtitle}</p><div class="course-card-bottom"><span>${l.level}</span><span>${state.completed.includes(l.id)?'已掌握 ✓':`${l.time} 分钟 · +100 XP`}</span></div></a>`).join('');}
function updateXp(){document.getElementById('xp-count').textContent=state.completed.length*100+(state.capstone?200:0);const toc=document.querySelector('.lesson-toc');if(toc){toc.querySelector('.progress-fill').style.width=state.completed.length/8*100+'%';toc.querySelector('.small.muted').textContent=`${state.completed.length} / 8 个理解挑战已通过`;toc.querySelectorAll('.toc-item').forEach(a=>{const n=Number(a.hash.split('/').at(-1));if(state.completed.includes(n))a.querySelector('.toc-index').textContent='✓';});}document.querySelector('.sidebar-bottom span:last-child').textContent=`Lv.${1+Math.floor(state.completed.length/2)}`;}
function course(id){
 const l=lessons.find(x=>x.id===id);if(!l)return notFound();state.last=id;save();
 shell(`<div class="lesson-layout"><article class="lesson-panel"><header class="lesson-banner"><div class="eyebrow">MISSION ${String(id).padStart(2,'0')} / ${l.level}</div><h1>${l.title}</h1><p>${l.mission}</p><div class="pills" style="margin-top:17px"><span class="pill">${icon(l.icon)}${l.time} 分钟</span><span class="pill">理解挑战 +100 XP</span><span class="pill" id="lesson-status">${state.completed.includes(id)?'已通过理解挑战':'随时可探索，无需解锁'}</span></div></header><div class="lesson-body"><h2>先怀疑一个直觉</h2><p>${l.misconception}</p><div class="principle">${l.principle}</div>${l.sections.map(s=>`<h2>${s.heading}</h2><p>${s.text}</p>`).join('')}<div class="analogy"><div class="analogy-label">${icon('people')}把它放进人类社会</div><p>${l.analogy}</p><p class="limit">类比到这里为止：${l.limit}</p></div><h2>看见信息怎样流动</h2><pre><code>${esc(l.code)}</code></pre><h2>现在，换你来做</h2><p>${l.practice}</p><a class="btn soft" href="#${l.lab}">${icon(l.icon)}${l.labLabel} ${icon('arrow')}</a><section class="quiz" aria-labelledby="quiz-title"><div class="eyebrow">不考记忆，考一次判断</div><h3 id="quiz-title">${l.question}</h3><div>${l.options.map((o,i)=>`<button class="choice" data-answer="${i}"><span class="choice-letter">${'ABC'[i]}</span><span>${o}</span></button>`).join('')}</div><div id="quiz-feedback" aria-live="polite"></div></section><h2>试着把它教给另一个人</h2><p>用自己的话解释：${l.summary}举一个这条原则失效或容易被误用的例子。</p><label class="visually-hidden" for="lesson-note">第 ${id} 关的理解笔记</label><textarea id="lesson-note" class="note-field" maxlength="5000" placeholder="如果我只能用三句话解释……">${esc(state.notes[id]||'')}</textarea><button class="btn light" id="save-note">${icon('book')}保存我的理解</button><div class="lesson-next">${id>1?`<a class="text-link" href="#/course/${id-1}">← 上一关</a>`:`<a class="text-link" href="#/">返回探索首页</a>`}<a class="btn primary" href="#${id===8?'/build':`/course/${id+1}`}">${id===8?'组装最小 Agent':'探索下一关'} ${icon('arrow')}</a></div></div></article><aside class="lesson-toc"><div class="card"><div style="grid-column:1/-1"><h3>八站之后，看懂本质。</h3><div class="progress-track"><div class="progress-fill" style="width:${state.completed.length/8*100}%"></div></div><p class="small muted">${state.completed.length} / 8 个理解挑战已通过</p></div>${lessons.map(x=>`<a href="#/course/${x.id}" class="toc-item ${x.id===id?'active':''}" ${x.id===id?'aria-current="step"':''}><span class="toc-index">${state.completed.includes(x.id)?'✓':String(x.id).padStart(2,'0')}</span>${x.subtitle}</a>`).join('')}</div><div class="callout">${icon('sprout')}不必一次学完。答错时先看解释，再动手试验。这里没有倒计时，也不会因为暂停而丢掉进度。</div></aside></div>`,'/course/1',`学习路线 / 第 ${id} 关`);
 document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answerQuestion(l,Number(b.dataset.answer)));
 if(Number.isInteger(state.answers[id]))showAnswer(l,state.answers[id]);
 document.getElementById('save-note').onclick=()=>{state.notes[id]=document.getElementById('lesson-note').value.trim();save();toast('理解笔记已保存在这台设备。');};
}
function answerQuestion(l,answer){state.answers[l.id]=answer;const isNew=answer===l.answer&&!state.completed.includes(l.id);if(isNew){state.completed.push(l.id);state.last=Math.min(8,l.id+1);}save();showAnswer(l,answer);updateXp();if(isNew){toast('理解挑战通过 · +100 XP');document.getElementById('lesson-status').textContent='已通过理解挑战';}}
function showAnswer(l,answer){if(answer<0||answer>=l.options.length)return;document.querySelectorAll('[data-answer]').forEach(b=>{const i=Number(b.dataset.answer);b.classList.toggle('correct',i===answer&&i===l.answer);b.classList.toggle('wrong',i===answer&&i!==l.answer);b.setAttribute('aria-pressed',String(i===answer));});document.getElementById('quiz-feedback').innerHTML=`<div class="feedback ${answer!==l.answer?'error':''}"><strong>${answer===l.answer?'抓住本质了。':'这个判断值得再想一下。'}</strong><br>${l.explanations[answer]}${answer===l.answer?`<p style="margin:8px 0 0">带走这句话：${l.summary}</p>`:'<br>可以换一个选项，也可以先去做实验。'}</div>`;}

let labState={tools:true,feedback:true,budget:2,step:0};
function labTabs(active){return `<div class="tabs" aria-label="实验导航"><a class="tab ${active==='loop'?'active':''}" href="#/lab">01 反馈循环</a><a class="tab ${active==='context'?'active':''}" href="#/lab/context">02 上下文桌面</a><a class="tab ${active==='team'?'active':''}" href="#/lab/team">03 协作悖论</a></div>`;}
function makeTrace(){const a=[{role:'模型请求',stage:0,text:'read_file("archive.txt") · 调用 call_1'}];if(!labState.tools){a.push({role:'执行器',stage:1,text:'拒绝：read_file 不在允许工具列表。未读取任何文件。'},{role:'最终报告',stage:3,text:'无法确认最新地址：当前没有读取资料的能力。',result:'没有工具，语言无法接触文件。你需要提供读取能力或由用户提供材料。',ok:false});return a;}a.push({role:'执行器',stage:1,text:'权限与路径检查通过。读取 archive.txt。'},{role:'工具结果',stage:2,text:'call_1 → 「旧址：松林路 8 号。新址请查 current.txt。」'});if(!labState.feedback){a.push({role:'调度器',stage:3,text:'工具已执行，但结果没有进入下一轮上下文。停止：反馈断开。',result:'执行和获知结果是两件事。请把工具结果连同调用 ID 交回模型，才有依据决定下一步。',ok:false});return a;}a.push({role:'模型请求',stage:0,text:'根据已返回的文件指引，请求 read_file("current.txt") · 调用 call_2'});if(labState.budget<2){a.push({role:'调度器',stage:1,text:'达到工具调用预算。call_2 未执行。'},{role:'部分报告',stage:3,text:'发现旧址已失效，新址仍未核实。停止：预算耗尽。',result:'一次读取只能发现线索。预算用完时应说明缺口，不能把旧址或猜测当成最新地址。',ok:false});return a;}a.push({role:'执行器',stage:1,text:'权限与路径检查通过。读取 current.txt。'},{role:'工具结果',stage:2,text:'call_2 → 「当前生效地址：银杏路 21 号。」'},{role:'最终报告',stage:3,text:'当前生效地址为银杏路 21 号。来源：current.txt。',result:'闭环成立：从旧资料获得线索，再读取当前资料，并把结论绑定到证据。完成的是本题资料核查，尚未核实真实世界中的地址。',ok:true});return a;}
function loopLab(){shell(`<div class="page-intro"><div class="eyebrow">THE LAB / 不妨亲手弄坏它</div><h1>少一根连线，还能办成事吗？</h1><p>同一条任务，改变工具、反馈和预算。观察一次行动从哪里开始，又为什么停止。</p></div>${labTabs('loop')}<div class="lab-grid"><section class="card lab-settings"><h3>你的控制台</h3><div class="field"><label for="enable-tools">开放读取工具 <input id="enable-tools" type="checkbox" ${labState.tools?'checked':''}></label><small>工具只读取本实验的两份虚拟文件。</small></div><div class="field"><label for="enable-feedback">把结果交回模型 <input id="enable-feedback" type="checkbox" ${labState.feedback?'checked':''}></label><small>关掉后，工具仍然执行，但下一轮看不到结果。</small></div><div class="field"><label for="step-budget">工具调用预算 <b id="budget-label">${labState.budget} 次</b></label><input id="step-budget" type="range" min="1" max="4" value="${labState.budget}"><small>最多允许多少次读取。更多预算不会强迫系统多做动作。</small></div><button class="btn primary" id="lab-next">执行下一步 ${icon('arrow')}</button><button class="btn soft" id="lab-run">运行到结束</button><button class="btn light" id="lab-reset">${icon('loop')}重置这次实验</button></section><section class="lab-main"><div class="card"><div class="lab-task"><span class="node-icon">${icon('flag')}</span><div><strong>找到实验局当前生效的地址，并注明来源。</strong><small>第一份资料 archive.txt 已过期；另一份资料藏着最新地址。</small></div></div><div id="lab-flow" class="lab-flow"></div><div class="terminal"><div class="terminal-top"><span class="terminal-dot"></span><span class="terminal-dot"></span><span class="terminal-dot"></span><span>可观察的事件日志 / TEACHING SIMULATION</span></div><div id="lab-log" class="terminal-lines" aria-live="polite"></div></div><div id="lab-result" aria-live="polite"></div></div><p class="lab-footnote">${icon('flask')}确定规则驱动的教学模拟，不调用真实模型、不读取你的文件。日志展示工具请求和事件，不是模型的内部思维。可在<a class="source-link" href="#/build">最终挑战</a>下载对应 Python 模拟。</p><details class="disclosure"><summary>下一次试什么？</summary><p>① 工具关闭时试一次。② 只关闭结果回传。③ 工具与反馈都打开，预算从 1 调到 2。④ 预算调到 4：为什么没有多读两次？</p></details></section></div>`,'/lab','交互实验室 / 反馈循环');
 for(const [id,key] of [['enable-tools','tools'],['enable-feedback','feedback']])document.getElementById(id).onchange=e=>{labState[key]=e.target.checked;labState.step=0;renderLab();};
 document.getElementById('step-budget').oninput=e=>{labState.budget=Number(e.target.value);document.getElementById('budget-label').textContent=labState.budget+' 次';labState.step=0;renderLab();};
 document.getElementById('lab-next').onclick=()=>{labState.step=Math.min(labState.step+1,makeTrace().length);renderLab();};document.getElementById('lab-run').onclick=()=>{labState.step=makeTrace().length;renderLab();};document.getElementById('lab-reset').onclick=()=>{labState.step=0;renderLab();};renderLab();
}
function renderLab(){const trace=makeTrace(),visible=trace.slice(0,labState.step),last=visible.at(-1);document.getElementById('lab-flow').innerHTML=['模型决策','工具执行','结果回传','继续 / 停止'].map((s,i)=>`${i?'<span class="flow-arrow">→</span>':''}<span class="flow-stage ${last?.stage===i?'active':''}">${s}</span>`).join('');document.getElementById('lab-log').innerHTML=visible.length?visible.map(x=>`<div class="log-line"><span class="log-role">${x.role}</span><span class="log-text">${esc(x.text)}</span></div>`).join(''):'<div class="log-placeholder">任务已就绪。按「执行下一步」，看一次工具请求怎样产生。<br><br>目标 → 模型 → 工具 → 观察 → 下一步</div>';document.getElementById('lab-result').innerHTML=last?.result?`<div class="feedback ${last.ok?'':'error'}"><strong>${last.ok?'实验完成 · 有证据的交付':'实验停下来了 · 看看缺了什么'}</strong><br>${last.result}</div>`:'';document.getElementById('lab-next').disabled=labState.step>=trace.length;document.getElementById('lab-run').disabled=labState.step>=trace.length;}

const memoryCards=[{name:'用户的硬约束',cost:3,text:'需要容纳 20 人；不能预付。',type:'当前任务 · 必需'}, {name:'现行包场政策',cost:3,text:'可容纳 20 人；本次适用政策要求预付。',type:'题目已核实 · 当前有效'}, {name:'旧版包场政策',cost:2,text:'去年允许到店付款；已明确失效。',type:'历史记录 · 不再适用'}, {name:'甜点菜单',cost:2,text:'抹茶蛋糕、草莓挞、拿铁。',type:'新消息 · 与支付决策无关'}, {name:'装修描述',cost:1,text:'落地窗，木质桌椅，适合拍照。',type:'新消息 · 非关键证据'}, {name:'聊天礼貌用语',cost:1,text:'你好！谢谢你的帮助。',type:'最新消息 · 可省略'}];
let contextState={budget:8,selected:[2,3,4,5],evaluated:false};
function contextLab(){shell(`<div class="page-intro"><div class="eyebrow">THE LAB / CONTEXT ENGINEERING</div><h1>桌面有限，什么值得带上？</h1><p>为 20 人预订咖啡店包场，用户不接受预付。选择要交给下一轮的材料，判断能否确认预订。</p></div>${labTabs('context')}<div class="lab-grid"><section class="card"><h3>上下文预算</h3><div class="field"><label for="context-budget">桌面大小 <b id="context-budget-label">${contextState.budget} 格</b></label><input id="context-budget" type="range" min="4" max="12" value="${contextState.budget}"><small>格数是教学单位，不等于真实 token 数。</small></div><div class="results-grid" style="grid-template-columns:1fr 1fr"><div class="metric"><b id="context-used">0</b><small>已用空间</small></div><div class="metric"><b id="context-free">0</b><small>剩余空间</small></div></div><button class="btn soft" id="select-relevant" style="width:100%">按任务挑选材料</button><button class="btn light" id="select-recent" style="width:100%;margin-top:10px">只带最近的消息</button><p class="lab-footnote">同样的容量，选择不同材料，得到的决策条件就不同。你也可以手动勾选。</p></section><section class="card"><div class="section-head" style="margin:0 0 15px"><h2>资料架</h2><span class="pill">6 张证据卡</span></div><div class="memory-list">${memoryCards.map((c,i)=>`<label class="memory-item" id="memory-${i}"><input type="checkbox" data-memory="${i}" ${contextState.selected.includes(i)?'checked':''} style="accent-color:var(--green);width:18px;height:18px;flex-shrink:0"><span style="flex:1"><strong>${c.name}</strong><span class="small muted" style="display:block;margin-top:4px">${c.text}</span><span class="small muted">${c.type}</span></span><span class="tag">${c.cost} 格</span></label>`).join('')}</div><button class="btn primary" id="context-evaluate">用这些材料做判断 ${icon('arrow')}</button><div id="context-result" aria-live="polite"></div><p class="lab-footnote">本实验按预设的证据依赖判断资料是否充分，不测量模型的真实注意力或记忆能力。未选材料不会被规则悄悄补回。</p></section></div>`,'/lab','交互实验室 / 上下文桌面');
 document.querySelectorAll('[data-memory]').forEach(el=>el.onchange=()=>{const id=Number(el.dataset.memory);contextState.selected=el.checked?[...contextState.selected,id]:contextState.selected.filter(x=>x!==id);contextState.evaluated=false;renderContext();});document.getElementById('context-budget').oninput=e=>{contextState.budget=Number(e.target.value);contextState.evaluated=false;renderContext();};document.getElementById('select-relevant').onclick=()=>{contextState.selected=contextState.budget>=6?[0,1]:[0];contextState.evaluated=false;renderContext();};document.getElementById('select-recent').onclick=()=>{let remaining=contextState.budget;contextState.selected=[];for(const i of [5,4,3,2,1,0])if(memoryCards[i].cost<=remaining){contextState.selected.push(i);remaining-=memoryCards[i].cost;}contextState.evaluated=false;renderContext();};document.getElementById('context-evaluate').onclick=()=>{contextState.evaluated=true;renderContext();};renderContext();}
function renderContext(){const used=contextState.selected.reduce((sum,i)=>sum+memoryCards[i].cost,0);document.getElementById('context-used').textContent=used;document.getElementById('context-free').textContent=contextState.budget-used;document.getElementById('context-budget-label').textContent=contextState.budget+' 格';document.querySelectorAll('[data-memory]').forEach(el=>{const i=Number(el.dataset.memory);el.checked=contextState.selected.includes(i);document.getElementById(`memory-${i}`).classList.toggle('selected',el.checked);});let text='',ok=false;const has=i=>contextState.selected.includes(i);if(used>contextState.budget)text='材料超出预算。请缩减材料或增加桌面容量；程序不能假装全部都已送入上下文。';else if(contextState.evaluated){if(has(0)&&has(1)){ok=true;text='发现明确冲突：用户不能预付，而现行政策要求预付。因此不能直接确认。下一步应找其他店，或请用户决定是否改变条件。'+(has(2)?' 旧政策已失效，不能用它覆盖当前政策。':'');}else if(!has(0))text='缺少用户的硬约束。即使知道店铺政策，也无法判断它是否满足本次要求。需要找回任务条件。';else if(!has(1))text=has(2)?'你带了用户约束和旧政策，但缺少当前有效政策。旧版明确已失效，不能据此确认。下一步应查询现行规定。':'约束有了，但没有当前店铺政策，无法判断条件是否匹配。先补证据。';}document.getElementById('context-result').innerHTML=text?`<div class="feedback ${ok?'':'error'}"><strong>${ok?'材料充分 · 正确识别冲突':'还不能确认预订'}</strong><br>${text}</div>`:'';}

function sourceLinks(a){return a.sources.map(s=>`<a class="source-link" href="${s.url}" target="_blank" rel="noopener noreferrer">${s.label} ↗</a>`).join('');}
function atlas(){shell(`<div class="page-intro"><div class="eyebrow">FIELD GUIDE / 七种生长方式</div><h1>同一个循环，不同的性格。</h1><p>工具如何接入？记忆放在哪里？谁来限制行动？用相同的六个问题，拆开七个 Agent 的设计。</p><div class="pills" style="margin-top:17px"><span class="pill">一手来源 · 2026.09.12 核查</span><span class="pill">设计解读，不是性能排名</span><a class="btn soft" href="#/compare">${icon('layers')}并排比较两个 Agent</a></div></div><div class="atlas-grid">${agents.map(a=>`<article class="card agent-card"><div class="agent-head"><div class="agent-logo">${esc(a.symbol)}</div><div><h2>${a.name}</h2><small>${a.type}</small></div></div><p>${a.tagline}</p><div class="pills">${a.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div><p>${a.what}</p><a class="btn" href="#/atlas/${a.id}">拆开看看 ${icon('arrow')}</a></article>`).join('')}</div><div class="mission"><h3>先问系统问题，再问模型名字。</h3><p>这七个项目不是七个基础模型。阅读时，把「官方描述」与「教学归纳」分开：每个详情页都有来源；取舍和社会映射是基于架构的解读，功能可能随版本变化。</p></div>`,'/atlas','Agent 图鉴');}
function agentDetail(id){const a=agents.find(x=>x.id===id);if(!a)return notFound();shell(`<a class="text-link" href="#/atlas">← 返回 Agent 图鉴</a><header class="detail-header"><div class="agent-logo">${esc(a.symbol)}</div><div><div class="eyebrow">${a.type}</div><h1>${a.name}</h1><p>${a.tagline}</p></div></header><div class="pills">${a.tags.map(t=>`<span class="pill">${t}</span>`).join('')}<span class="pill">资料核查：2026.09.12</span><a class="btn soft" href="#/compare/${a.id}">并排比较 ${icon('arrow')}</a></div><div class="detail-grid">${[['01','它究竟是什么','what'],['02','循环怎样运转','loop'],['03','上下文与记忆在哪里','context'],['04','谁决定它能做什么','boundary'],['05','如何长出新能力','extension'],['06','选择什么，也意味着放弃什么','tradeoff']].map(([n,t,key])=>`<section class="card"><div class="card-kicker">${n} / ${key==='tradeoff'?'架构解读':'系统拆解'}</div><h3>${t}</h3><p>${a[key]}</p></section>`).join('')}</div><div class="mission"><div class="eyebrow">从产品走向可迁移的理解</div><h3 style="margin-top:14px">把它放进人类社会</h3><p>${a.lesson}</p><p class="small" style="margin-top:10px">这是对信息流、分工和制度的类比，不表示模型具有人的意识、动机或责任能力。</p></div><section class="card"><h3>继续读一手资料</h3><p class="small muted" style="margin-top:7px">以上为核查时的文档描述。具体能力与默认设置以你实际使用的版本和配置为准。</p><div class="source-list">${sourceLinks(a)}</div></section>`,'/atlas',`Agent 图鉴 / ${a.name}`);}
let comparison={left:'codex',right:'pi'};
function compare(id){if(agents.some(a=>a.id===id)){comparison.left=id;if(comparison.right===id)comparison.right=id==='pi'?'codex':'pi';}shell(`<div class="page-intro"><div class="eyebrow">COMPARE / 从取舍读懂架构</div><h1>不问谁赢，问为什么不同。</h1><p>固定比较维度，观察两个系统把责任放在什么地方。模型能力、运行环境和配置会共同影响最终效果。</p></div><div class="compare-controls"><label for="compare-left">左侧 Agent <select id="compare-left">${agents.map(a=>`<option value="${a.id}" ${a.id===comparison.left?'selected':''}>${a.name}</option>`).join('')}</select></label><span class="muted">↔</span><label for="compare-right">右侧 Agent <select id="compare-right">${agents.map(a=>`<option value="${a.id}" ${a.id===comparison.right?'selected':''}>${a.name}</option>`).join('')}</select></label></div><div id="compare-result" aria-live="polite"></div><p class="lab-footnote">比较依据官方文档，非性能实测。社会类比与设计取舍属于教学归纳。手机上可横向滑动表格。</p>`,'/atlas','Agent 图鉴 / 并排比较');for(const side of ['left','right'])document.getElementById('compare-'+side).onchange=e=>{comparison[side]=e.target.value;renderCompare();};renderCompare();}
function renderCompare(){const a=agents.find(x=>x.id===comparison.left),b=agents.find(x=>x.id===comparison.right);document.getElementById('compare-result').innerHTML=`${a.id===b.id?'<div class="feedback" style="margin-bottom:18px">目前选择了同一款 Agent。换一个对象，就能看见架构取舍。</div>':''}<div class="table-wrap"><table class="compare-table"><caption class="visually-hidden">${a.name} 与 ${b.name} 的架构比较</caption><thead><tr><th scope="col">比较维度</th><th scope="col">${a.name}</th><th scope="col">${b.name}</th></tr></thead><tbody>${[['what','定位'],['loop','执行循环'],['context','上下文与记忆'],['boundary','执行边界'],['extension','扩展方式'],['tradeoff','设计取舍'],['lesson','社会映射']].map(([key,label])=>`<tr><td>${label}</td><td>${a[key]}</td><td>${b[key]}</td></tr>`).join('')}<tr><td>官方资料</td><td>${sourceLinks(a)}</td><td>${sourceLinks(b)}</td></tr></tbody></table></div>`;}

let team={workers:2,contract:true,verify:true,coordination:1};
function society(){shell(`<section class="society-hero"><div class="eyebrow">AGENTS & SOCIETY / 一个更大的视角</div><h1>理解 Agent，也是在重新理解协作。</h1><p>当语言开始调用工具，问题就从「一句话说得好不好」变成「谁知道什么、谁能做什么、谁来验证」。这些问题，在人类社会里也并不陌生。</p></section><div class="society-grid">${socialMappings.map(s=>`<article class="card society-card">${icon(s.icon)}<h3>${s.human} ↔ ${s.agent}</h3><p>${s.text}</p><p class="limit">类比边界：${s.limit}</p></article>`).join('')}</div><div class="mission"><h3>组织不只是一群「更聪明的人」。</h3><p>信息如何流动、权限如何落实、评价是否忠于目标，决定了一群能力很强的个体是否能够合作。把这些关系放进可观察的实验，比给 Agent 贴人设更有帮助。</p><a class="btn primary" style="margin-top:18px" href="#/lab/team">开一间 Agent 工作室 ${icon('arrow')}</a></div><section class="card"><h2 style="font-size:1.2rem">三个值得带走的问题</h2><details class="disclosure"><summary>模型仍是语言模型，为什么能表现出复杂协作？</summary><p>语言可以表示任务、证据、规则与工具调用。运行程序把这些表示连接到实际操作，再把结果带回来。复杂行为可能来自模型与外部系统的组合，不必假设每一轮模型调用都拥有一个持续的内在自我。</p></details><details class="disclosure"><summary>多个 Agent 一致同意，为什么仍可能都错？</summary><p>它们可能读同一份旧材料、使用相似模型、共享同一错误前提。独立验证需要不同的信息路径，例如检查当前源码或实际运行一个被授权的测试；增加同源投票并不自动增加证据。</p></details><details class="disclosure"><summary>如果评价指标错了，会发生什么？</summary><p>系统会把努力投入可获得奖励的方向。把「完成任务」简化为「测试全绿」，可能激励删除失败测试。无论组织还是 Agent，都要让指标持续对应真正的目标，并检查指标之外的副作用。</p></details><p class="lab-footnote">上述映射是教学模型，不是关于意识、人格或人类组织可被完整还原成软件的科学结论。</p></section>`,'/society','社会的镜像');}
function teamLab(){shell(`<div class="page-intro"><div class="eyebrow">THE LAB / THE COORDINATION PARADOX</div><h1>四个聪明人，为什么还更慢？</h1><p>组建一间小工作室，修复博物馆网站搜索。界面和检索可以并行，接口与集成需要对齐。</p></div>${labTabs('team')}<div class="lab-grid"><section class="card"><h3>组织你的团队</h3><div class="field"><label for="team-size">执行者数量 <select id="team-size">${[1,2,4].map(n=>`<option value="${n}" ${team.workers===n?'selected':''}>${n} 个 Agent</option>`).join('')}</select></label></div><div class="field"><label for="team-contract">先共享接口约定 <input type="checkbox" id="team-contract" ${team.contract?'checked':''}></label><small>省略时，两项实现会基于不兼容的接口。</small></div><div class="field"><label for="team-verify">独立集成验收 <input type="checkbox" id="team-verify" ${team.verify?'checked':''}></label><small>用当前接口检查真实结果，而非再找一个角色投票。</small></div><div class="field"><label for="team-cost">每位额外成员的沟通成本 <b id="team-cost-label">${team.coordination}</b></label><input type="range" id="team-cost" min="0" max="4" value="${team.coordination}"><small>时间单位为场景参数，非行业实测。</small></div></section><section class="card"><div class="eyebrow">同一个任务 / 不同的组织方式</div><h2 style="font-size:1.23rem;margin-top:15px">修复网站搜索并验证</h2><div id="team-result" aria-live="polite"></div><p class="lab-footnote">规则模拟：接口对齐 2 单位，界面与检索各 6，集成 2，验收 3。未对齐会产生 4 单位修复工作；只有启用验收才发现并修复。最多两个实现任务可并行。每增加一人增加设定的同步耗时。</p><a class="source-link" href="#/society">回到社会映射，看看这像哪种组织问题 →</a></section></div>`,'/lab','交互实验室 / 协作悖论');document.getElementById('team-size').onchange=e=>{team.workers=Number(e.target.value);renderTeam();};document.getElementById('team-contract').onchange=e=>{team.contract=e.target.checked;renderTeam();};document.getElementById('team-verify').onchange=e=>{team.verify=e.target.checked;renderTeam();};document.getElementById('team-cost').oninput=e=>{team.coordination=Number(e.target.value);renderTeam();};renderTeam();}
function renderTeam(){const comm=(team.workers-1)*team.coordination;const implementation=team.workers===1?12:6;const rework=!team.contract&&team.verify?4:0;const time=(team.contract?2:0)+implementation+2+(team.verify?3:0)+rework+comm;const work=(team.contract?2:0)+12+2+(team.verify?3:0)+rework+comm;const ok=team.verify;document.getElementById('team-cost-label').textContent=team.coordination;document.getElementById('team-result').innerHTML=`<div class="results-grid"><div class="metric"><b>${time}</b><small>交付耗时 / 单位</small></div><div class="metric"><b>${work}</b><small>总工作量 / 单位</small></div><div class="metric"><b>${rework}</b><small>实际返工 / 单位</small></div></div><div>${[['实现关键路径',implementation],['同步与沟通',comm],['集成与验收',2+(team.verify?3:0)],['接口对齐 / 修复',(team.contract?2:0)+rework]].map(([n,v])=>`<div class="bar-row"><span>${n}</span><div class="bar-track"><div class="bar-value" style="width:${v/16*100}%"></div></div><span>${v} 单位</span></div>`).join('')}</div><div class="feedback ${ok?'':'error'}"><strong>${ok?'已通过本场景集成验收':'没有验收，完成状态未确认'}</strong><br>${!team.contract?(team.verify?'验收发现接口不一致，修复花了 4 单位。先对齐可以减少返工。':'界面和检索接口实际不匹配，但团队没有运行验收。日志看起来结束了，不等于任务成功。'):(team.verify?'接口约定一致，独立验收确认搜索能够正常集成。':'接口已对齐，但没有独立验收。不能把省下的检查时间称为可靠性提升。')}${team.workers===4?'<br>四位执行者只有两个可并行实现任务，多出来的人增加沟通却不能缩短实现关键路径。':''}</div>`;}

let order=[2,0,4,1,3];const pieces=['把用户目标与约束加入消息','请求模型，读取回答或工具调用','如有工具调用：校验、执行、记录结果','把工具结果带回下一轮；检查预算与停止条件','没有工具调用或需停止：交付证据与未完成项'];
function build(){shell(`<div class="page-intro"><div class="eyebrow">FINAL MISSION / 从理解，到构建</div><h1>现在，亲手接通这个循环。</h1><p>用上下箭头排列控制流程。你不需要背代码，但要知道数据先去哪儿、谁执行、什么时候停止。</p></div><div class="two-col"><section class="card"><h2 style="font-size:1.2rem">组装你的最小 Agent</h2><p class="lab-footnote">这里把条件分支压成五张概念卡；实际程序中，工具分支返回模型步骤，终止分支退出。</p><div id="code-pieces" class="code-pieces"></div><button class="btn primary" id="check-order">检查我的设计 ${icon('arrow')}</button><div id="order-result" aria-live="polite"></div></section><aside class="card"><div class="eyebrow">带走一个能跑的实验</div><h2 style="font-size:1.2rem;margin:16px 0 12px">从 30 秒直觉，到一段循环。</h2><p class="muted" style="font-size:.89rem">Python 示例使用标准库与确定的模型替身，实际读取同目录样例资料。可以看到请求、权限校验、结果回传和预算耗尽。</p><a class="btn soft download-link" style="margin:20px 0" href="./agent_lab.py" download>${icon('download')}下载 Python 实验</a><pre style="background:#eff3e8;border-radius:8px;padding:14px;font-size:.79rem"><code>python agent_lab.py --budget 2\npython agent_lab.py --budget 1</code></pre><p class="lab-footnote">首次运行会在脚本旁创建专用的 agent_lab_files 样例目录；不会覆盖已有样例文件。不联网，不使用 API Key。真实模型调用属于下一阶段。</p></aside></div><div class="mission"><h3>真正的毕业标准：能够解释，也能够迁移。</h3><ul class="checkpoint-list"><li>关闭工具时，说清为什么不能完成。</li><li>把预算从 2 改为 1，准确报告部分完成。</li><li>指出哪一段代码负责执行，而不是生成请求。</li><li>说明接入真实模型后，哪些程序约束仍必须保留。</li></ul></div><section class="card"><h3>接入真实模型时，只替换模型边界</h3><p class="muted" style="margin-top:10px;font-size:.92rem">将示例的 policy 换成实际模型客户端，声明工具 schema，并完整保留模型的工具请求与结果消息。模型客户端的创建不等于发出请求；Base URL 是接口基础地址，Chat Completions 的路径是 /chat/completions，SDK 通常负责拼接。密钥只放环境变量或本地忽略文件，不能嵌入网页。</p><p class="muted" style="margin-top:10px;font-size:.92rem">先选择一套协议并用一次请求验证配置，再接工具回传和多轮循环。用模拟验收控制流，用真实任务检验模型能力；两类结果分开记录。</p><a class="source-link" href="#/course/8">回顾验收与终止条件 →</a></section>`,'/course/1','最终挑战 / 组装循环');renderPieces();document.getElementById('check-order').onclick=()=>{const correct=order.every((n,i)=>n===i);document.getElementById('order-result').innerHTML=`<div class="feedback ${correct?'':'error'}">${correct?'<strong>循环已接通。</strong><br>目标进入上下文，模型提出动作，程序执行并返回观察，达到终点时交付结果。记得：第 4 步在需要继续时回到第 2 步。':'<strong>还有一根线没有接好。</strong><br>先有目标，再请求模型；执行发生在请求之后；结果回传后才有下一轮依据；最后准确交付。按这个数据依赖再排一次。'}</div>`;if(correct&&!state.capstone){state.capstone=true;save();updateXp();toast('最终挑战通过 · +200 XP');}};}
function renderPieces(){document.getElementById('code-pieces').innerHTML=order.map((n,i)=>`<div class="code-piece"><span class="order">${i+1}</span><code>${pieces[n]}</code><button class="move-btn" data-move="${i}" data-dir="-1" ${i===0?'disabled':''} aria-label="上移：${pieces[n]}">↑</button><button class="move-btn" data-move="${i}" data-dir="1" ${i===order.length-1?'disabled':''} aria-label="下移：${pieces[n]}">↓</button></div>`).join('');document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.move),d=Number(b.dataset.dir);[order[i],order[i+d]]=[order[i+d],order[i]];renderPieces();document.getElementById('order-result').innerHTML='';const moved=document.querySelector(`[data-move="${i+d}"][data-dir="${d}"]`);if(moved&&!moved.disabled)moved.focus();else document.querySelector(`[data-move="${i+d}"]:not(:disabled)`)?.focus();});}
function notebook(){const notes=lessons.filter(l=>typeof state.notes[l.id]==='string'&&state.notes[l.id].trim());const revisit=lessons.filter(l=>Number.isInteger(state.answers[l.id])&&state.answers[l.id]!==l.answer);shell(`<div class="page-intro"><div class="eyebrow">YOUR FIELD NOTES / 理解的轨迹</div><h1>每一个「原来如此」，都算数。</h1><p>这里记录的是理解挑战和你自己的解释。学习进度只保存在这台设备的当前浏览器，不需要注册。</p></div><div class="results-grid"><div class="card metric"><b>${state.completed.length} / 8</b><small>已通过理解挑战</small></div><div class="card metric"><b>${state.completed.length*100+(state.capstone?200:0)}</b><small>通过挑战获得的 XP</small></div><div class="card metric"><b>${notes.length}</b><small>写下自己的理解</small></div></div><div class="two-col"><section class="card"><h2 style="font-size:1.2rem">你的探索护照</h2>${lessons.map(l=>`<div class="record-row">${icon(state.completed.includes(l.id)?'check':l.icon)}<div><strong>${String(l.id).padStart(2,'0')} · ${l.title}</strong><small>${state.completed.includes(l.id)?'理解挑战已通过':'等待你的发现'}</small></div><a class="btn soft" href="#/course/${l.id}">${state.completed.includes(l.id)?'回顾':'探索'}</a></div>`).join('')}<div class="record-row">${icon('flag')}<div><strong>最终挑战 · 组装循环</strong><small>${state.capstone?'流程排序已通过':'把八关知识拼起来'}</small></div><a href="#/build" class="btn soft">${state.capstone?'重温':'挑战'}</a></div></section><div><section class="card"><h2 style="font-size:1.2rem">值得再想一次</h2>${revisit.length?revisit.map(l=>`<div class="record-row"><div><strong>${l.title}</strong><small>最近一次判断仍有可改进之处</small></div><a class="btn soft" href="#/course/${l.id}">重试</a></div>`).join(''):`<div class="empty-state">${icon('sprout')}<p>${state.completed.length?'暂时没有待复习的判断。试着把原理讲给别人听。':'答错也没关系。值得重想的问题会留在这里。'}</p><a class="btn primary" href="#/course/${state.last||1}">继续探索 ${icon('arrow')}</a></div>`}</section><section class="card" style="margin-top:20px"><h2 style="font-size:1.2rem">我自己的解释</h2>${notes.length?notes.map(l=>`<details class="disclosure"><summary>${l.title}</summary><p style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(state.notes[l.id])}</p><a class="source-link" href="#/course/${l.id}">回到课程编辑 →</a></details>`).join(''):'<p class="muted" style="font-size:.9rem;margin-top:14px">每一关末尾都可以用自己的话解释原理。比起收藏一句话，把它讲清楚更有力量。</p>'}</section></div></div><div class="section-head"><span class="small muted">清除浏览器数据也会清除这些记录。</span><button class="text-link" id="reset-progress">重新开始学习</button></div><dialog id="reset-dialog" class="dialog"><h3>清除这台设备的学习记录？</h3><p>将清除关卡完成情况、答题记录与理解笔记。课程内容仍然可以随时访问。</p><div class="dialog-actions"><button class="btn light" id="cancel-reset">保留记录</button><button class="btn primary" id="confirm-reset">清除并重新开始</button></div></dialog>`,'/notebook','我的学习档案');const dialog=document.getElementById('reset-dialog');document.getElementById('reset-progress').onclick=()=>dialog.showModal();document.getElementById('cancel-reset').onclick=()=>dialog.close();document.getElementById('confirm-reset').onclick=()=>{state={completed:[],answers:{},notes:{},last:1,capstone:false};save();notebook();toast('已清除本设备的学习记录。');};}
function notFound(){shell(`<section class="not-found"><div class="eyebrow" style="justify-content:center">这条小路还没有地图</div><h1>没有找到这个实验。</h1><p class="muted">回到探索首页，选择一条已经开放的路线。</p><a class="btn primary" href="#/">返回首页 ${icon('arrow')}</a></section>`,'/','未找到页面');}
function route(){const path=(location.hash.slice(1)||'/').split('?')[0];if(path==='/')home();else if(/^\/course\/[1-8]$/.test(path))course(Number(path.split('/')[2]));else if(path==='/course')course(state.last>=1&&state.last<=8?state.last:1);else if(path==='/lab')loopLab();else if(path==='/lab/context')contextLab();else if(path==='/lab/team')teamLab();else if(path==='/atlas')atlas();else if(path.startsWith('/atlas/'))agentDetail(path.split('/')[2]);else if(path==='/compare'||path.startsWith('/compare/'))compare(path.split('/')[2]);else if(path==='/society')society();else if(path==='/notebook')notebook();else if(path==='/build')build();else notFound();}
window.addEventListener('hashchange',()=>{route();window.scrollTo(0,0);document.getElementById('main')?.focus({preventScroll:true});});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('.sidebar.open'))document.querySelector('.mobile-scrim')?.click();});
document.querySelector('.skip-link').addEventListener('click',e=>{e.preventDefault();document.getElementById('main')?.focus();});
route();

// Expose only the same read and navigation actions that the visible UI offers.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 const tool={name:'open_agent_lesson',title:'打开 Agent 课程',description:'打开指定关卡，不提交答案或改变完成状态。',inputSchema:{type:'object',properties:{lesson:{type:'integer',minimum:1,maximum:8}},required:['lesson'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async(input)=>{if(!input||!Number.isInteger(input.lesson)||input.lesson<1||input.lesson>8||Object.keys(input).some(k=>k!=='lesson'))throw new Error('lesson 必须为 1 至 8 的整数。');history.replaceState(null,'',`#/course/${input.lesson}`);route();window.scrollTo(0,0);return {opened:input.lesson,title:lessons[input.lesson-1].title};}};
 try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}
}
